    private static final Logger log = LoggerFactory.getLogger(BlockchainService.class);

    @Value("${blockchain.rpc-url}")
    private String rpcUrl;

    // 🛡️ Phase 3: RPC Failover — danh sách RPC backup, phân cách bằng dấu phẩy
    @Value("${blockchain.rpc-url-backup:}")
    private String rpcUrlBackup;

    @Value("${blockchain.private-key}")
    private String privateKey;

    @Value("${blockchain.chain-id:11155111}")
    private long chainId;

    // 🛡️ Phase 3: Gas price threshold (Gwei) — từ chối nếu gas vượt ngưỡng
    @Value("${blockchain.gas-price-max-gwei:100}")
    private long gasPriceMaxGwei;

    private Web3j web3j;
    private Credentials credentials;
    private List<String> rpcUrls; // 🛡️ Failover list

    @org.springframework.beans.factory.annotation.Autowired
    private iuh.se.kltn.backend.modules.contract.repository.BlockchainNonceRepository nonceRepository;

    @PostConstruct
    public void init() {
        // 🛡️ Phase 3: Build RPC failover list
        rpcUrls = new ArrayList<>();
        rpcUrls.add(rpcUrl);
        if (rpcUrlBackup != null && !rpcUrlBackup.isEmpty()) {
            for (String backup : rpcUrlBackup.split(",")) {
                if (!backup.trim().isEmpty()) rpcUrls.add(backup.trim());
            }
        }
        
        OkHttpClient httpClient = new OkHttpClient.Builder()
                .connectTimeout(120, TimeUnit.SECONDS)
                .readTimeout(120, TimeUnit.SECONDS)
                .writeTimeout(120, TimeUnit.SECONDS)
                .build();
        this.web3j = Web3j.build(new HttpService(rpcUrl, httpClient, false));
        this.credentials = Credentials.create(privateKey);
        log.info("🔗 BlockchainService initialized with {} RPC endpoint(s), Chain ID: {}", rpcUrls.size(), chainId);
    }

    @PreDestroy
    public void shutdown() {
        if (web3j != null) {
            web3j.shutdown();
            log.info("Web3j connection shut down.");
        }
    }

    public boolean isConfigured() {
        return privateKey != null && !privateKey.isEmpty();
    }

    /**
     * 🛡️ PHASE 3: DB-backed distributed nonce management.
     * Uses SELECT FOR UPDATE to prevent concurrent instances from getting the same
     * nonce.
     * Must be called within a @Transactional context.
     */
    @org.springframework.transaction.annotation.Transactional
    public BigInteger getNonce() throws Exception {
        String walletAddress = credentials.getAddress().toLowerCase();

        // Sync with on-chain nonce first
        EthGetTransactionCount ethGetTransactionCount = web3j.ethGetTransactionCount(
                credentials.getAddress(), DefaultBlockParameterName.PENDING).send();
        long onChainNonce = ethGetTransactionCount.getTransactionCount().longValue();

        // Atomic DB operation with pessimistic lock
        var nonceOpt = nonceRepository.findByWalletAddressForUpdate(walletAddress);
        iuh.se.kltn.backend.modules.contract.entity.BlockchainNonce nonceEntity;

        if (nonceOpt.isPresent()) {
            nonceEntity = nonceOpt.get();
            // Always take the max of DB and on-chain
            if (onChainNonce > nonceEntity.getCurrentNonce()) {
                nonceEntity.setCurrentNonce(onChainNonce);
            }
        } else {
            nonceEntity = iuh.se.kltn.backend.modules.contract.entity.BlockchainNonce.builder()
                    .walletAddress(walletAddress)
                    .currentNonce(onChainNonce)
                    .build();
        }

        long reservedNonce = nonceEntity.getCurrentNonce();
        nonceEntity.setCurrentNonce(reservedNonce + 1);
        nonceEntity.setLastSyncedAt(java.time.LocalDateTime.now());
        nonceRepository.save(nonceEntity);

        log.debug("Nonce reserved: {} for wallet: {}", reservedNonce, walletAddress);
        return BigInteger.valueOf(reservedNonce);
    }

    // 👇👇👇 DÁN LẠI CHUỖI BYTECODE DÀI CỦA BẠN VÀO ĐÂY 👇👇👇
    private static final String CONTRACT_BINARY = "";

    public String deployRentalContract(
            String landlordAddress,
            String tenantAddress,
            String roomName,
            String contractHash,
            BigInteger rentAmount,
            BigInteger depositAmount,
            BigInteger elecPrice,
            BigInteger waterPrice,
            BigInteger internetPrice,
            BigInteger startDate,
            BigInteger endDate,
            BigInteger latePenaltyPercent) throws Exception {

        // Cấu hình Timeout 120 giây
        OkHttpClient httpClient = new OkHttpClient.Builder()
                .connectTimeout(120, TimeUnit.SECONDS)
                .readTimeout(120, TimeUnit.SECONDS)
                .writeTimeout(120, TimeUnit.SECONDS)
                .build();

        Web3j web3j = Web3j.build(new HttpService(rpcUrl, httpClient, false));
        Credentials credentials = Credentials.create(privateKey);

        org.web3j.abi.datatypes.DynamicArray<Uint256> uintParams = new org.web3j.abi.datatypes.DynamicArray<>(
                Uint256.class,
                new Uint256(rentAmount),
                new Uint256(depositAmount),
                new Uint256(elecPrice),
                new Uint256(waterPrice),
                new Uint256(internetPrice),
                new Uint256(startDate),
                new Uint256(endDate),
                new Uint256(latePenaltyPercent));

        String encodedConstructor = FunctionEncoder.encodeConstructor(Arrays.asList(
                new Address(landlordAddress),
                new Address(tenantAddress),
                new Utf8String(roomName),
                new Utf8String(contractHash),
                uintParams));

        String data = CONTRACT_BINARY + encodedConstructor;

        BigInteger nonce = getNonce();
        BigInteger gasLimit = BigInteger.valueOf(6000000);
        BigInteger currentGasPrice = web3j.ethGasPrice().send().getGasPrice();
        // +20% buffer cho gas price
        BigInteger gasPrice = currentGasPrice.add(currentGasPrice.divide(BigInteger.valueOf(5)));
        
        // 🛡️ Phase 3: Gas threshold check
        checkGasThreshold(gasPrice, "deployRentalContract");

        log.info("Params: Landlord={}, Tenant={}, Room={}, Hash={}", landlordAddress, tenantAddress, roomName,
                contractHash);
        log.info("UintParams: rent={}, deposit={}, start={}, end={}, penalty={}", rentAmount, depositAmount, startDate,
                endDate, latePenaltyPercent);

        RawTransaction rawTransaction = RawTransaction.createContractTransaction(
                nonce, gasPrice, gasLimit, BigInteger.ZERO, data);

        byte[] signedMessage = TransactionEncoder.signMessage(rawTransaction, chainId, credentials);
        String hexValue = Numeric.toHexString(signedMessage);

        EthSendTransaction transactionResponse = web3j.ethSendRawTransaction(hexValue).send();

        if (transactionResponse.hasError()) {
            // Nonce reset is handled by DB sync on next call
            throw new RuntimeException("Lỗi Deploy Blockchain: " + transactionResponse.getError().getMessage());
        }

        String transactionHash = transactionResponse.getTransactionHash();
        log.info("🚀 Đang Deploy hợp đồng... Tx Hash: {}", transactionHash);

        for (int i = 0; i < 60; i++) {
            Thread.sleep(5000);
            TransactionReceipt receipt = web3j.ethGetTransactionReceipt(transactionHash).send().getTransactionReceipt()
                    .orElse(null);
            if (receipt != null) {
                if (receipt.isStatusOK()) {
                    log.info("✅ Deploy thành công! Address: {}", receipt.getContractAddress());
                    return receipt.getContractAddress();
                } else {
                    log.error("❌ Giao dịch thất bại! Receipt status = 0. Tx Hash: {}", transactionHash);
                    throw new RuntimeException("Giao dịch Deploy thất bại on-chain. Tx Hash: " + transactionHash);
                }
            }
        }

        throw new RuntimeException("Timeout khi đợi xác nhận Deploy.");
    }

    public Map<String, Object> readContractData(String contractAddress) throws Exception {
        Map<String, Object> result = new LinkedHashMap<>();

        result.put("rentAmount", readUint256(web3j, contractAddress, "rentAmount"));
        result.put("depositAmount", readUint256(web3j, contractAddress, "depositAmount"));
        result.put("roomName", readString(web3j, contractAddress, "roomName"));
        result.put("contractHash", readString(web3j, contractAddress, "contractHash"));
        result.put("elecPrice", readUint256(web3j, contractAddress, "elecPrice"));
        result.put("waterPrice", readUint256(web3j, contractAddress, "waterPrice"));
        result.put("internetPrice", readUint256(web3j, contractAddress, "internetPrice"));
        result.put("startDate", readUint256(web3j, contractAddress, "startDate"));
        result.put("endDate", readUint256(web3j, contractAddress, "endDate"));
        result.put("latePenaltyPercent", readUint256(web3j, contractAddress, "latePenaltyPercent"));

        String onChainLandlord = readAddress(web3j, contractAddress, "landlord");
        if (onChainLandlord != null)
            result.put("landlordAddress", onChainLandlord.toLowerCase());

        String onChainTenant = readAddress(web3j, contractAddress, "tenant");
        if (onChainTenant != null)
            result.put("tenantAddress", onChainTenant.toLowerCase());

        result.put("unpaidBillCount", readUint256(web3j, contractAddress, "unpaidBillCount"));

        return result;
    }

    @SuppressWarnings("rawtypes")
    private BigInteger readUint256(Web3j web3j, String contractAddress, String functionName) throws Exception {
        Function function = new Function(functionName,
                Collections.emptyList(),
                Arrays.asList(new TypeReference<Uint256>() {
                }));

        String encodedFunction = FunctionEncoder.encode(function);
        EthCall response = web3j.ethCall(
                Transaction.createEthCallTransaction(null, contractAddress, encodedFunction),
                DefaultBlockParameterName.LATEST).send();

        List<Type> decoded = FunctionReturnDecoder.decode(response.getValue(), function.getOutputParameters());
        if (decoded.isEmpty())
            return BigInteger.ZERO;
        return ((Uint256) decoded.get(0)).getValue();
    }

    @SuppressWarnings("rawtypes")
    private String readString(Web3j web3j, String contractAddress, String functionName) throws Exception {
        Function function = new Function(functionName,
                Collections.emptyList(),
                Arrays.asList(new TypeReference<Utf8String>() {
                }));

        String encodedFunction = FunctionEncoder.encode(function);
        EthCall response = web3j.ethCall(
                Transaction.createEthCallTransaction(null, contractAddress, encodedFunction),
                DefaultBlockParameterName.LATEST).send();

        List<Type> decoded = FunctionReturnDecoder.decode(response.getValue(), function.getOutputParameters());
        if (decoded.isEmpty())
            return "";
        return decoded.get(0).getValue().toString();
    }

    @SuppressWarnings("rawtypes")
    private String readAddress(Web3j web3j, String contractAddress, String functionName) throws Exception {
        Function function = new Function(functionName,
                Collections.emptyList(),
                Arrays.asList(new TypeReference<Address>() {
                }));

        String encodedFunction = FunctionEncoder.encode(function);
        EthCall response = web3j.ethCall(
                Transaction.createEthCallTransaction(null, contractAddress, encodedFunction),
                DefaultBlockParameterName.LATEST).send();

        List<Type> decoded = FunctionReturnDecoder.decode(response.getValue(), function.getOutputParameters());
        if (decoded.isEmpty())
            return "";
        return decoded.get(0).getValue().toString();
    }

    @SuppressWarnings("rawtypes")
    private String sendContractTransaction(String contractAddress, String functionName,
            List<Type> inputParams) throws Exception {
        Function function = new Function(functionName, inputParams, Collections.emptyList());
        String encodedFunction = FunctionEncoder.encode(function);

        BigInteger nonce = getNonce();
        BigInteger gasLimit = BigInteger.valueOf(800000);
        BigInteger currentGasPrice = web3j.ethGasPrice().send().getGasPrice();
        BigInteger gasPrice = currentGasPrice.add(currentGasPrice.divide(BigInteger.valueOf(5)));
        
        // 🛡️ Phase 3: Gas threshold check
        checkGasThreshold(gasPrice, functionName);

        RawTransaction rawTransaction = RawTransaction.createTransaction(
                nonce, gasPrice, gasLimit, contractAddress, BigInteger.ZERO, encodedFunction);

        byte[] signedMessage = TransactionEncoder.signMessage(rawTransaction, chainId, credentials);
        String hexValue = Numeric.toHexString(signedMessage);

        EthSendTransaction transactionResponse = web3j.ethSendRawTransaction(hexValue).send();

        if (transactionResponse.hasError()) {
            // Nonce reset is handled by DB sync on next call
            throw new RuntimeException(
                    "Lỗi Blockchain (" + functionName + "): " + transactionResponse.getError().getMessage());
        }

        String txHash = transactionResponse.getTransactionHash();
        log.info("🔗 Gửi tx {}, Hash: {}", functionName, txHash);

        for (int i = 0; i < 40; i++) {
            Thread.sleep(3000);
            TransactionReceipt receipt = web3j.ethGetTransactionReceipt(txHash).send()
                    .getTransactionReceipt().orElse(null);
            if (receipt != null) {
                if (receipt.isStatusOK()) {
                    log.info("✅ {} thành công! Tx: {}", functionName, txHash);
                    return txHash;
                } else {
                    throw new RuntimeException("Giao dịch " + functionName + " thất bại on-chain: " + txHash);
                }
            }
        }

        throw new RuntimeException("Hết thời gian chờ xác nhận " + functionName);
    }

    public String registerExternalBill(String contractAddress, long billId, BigInteger amount) throws Exception {
        return sendContractTransaction(contractAddress, "registerExternalBill", Arrays.asList(
                new Uint256(BigInteger.valueOf(billId)),
                new Uint256(amount)));
    }

